function ConnectionCheck({onBack}:{onBack:()=>void}){
  const[state,setState]=useState('Lagos');
  const[testing,setTesting]=useState(false);
  const[result,setResult]=useState<{ping:number;download:number;upload:number}|null>(null);
  const[error,setError]=useState('');
  const run=async()=>{setTesting(true);setError('');try{
    const pingSamples:number[]=[];
    for(let i=0;i<3;i++){const t=Date.now();await fetch('https://speed.cloudflare.com/__down?bytes=1000&seed='+Math.random());pingSamples.push(Date.now()-t)}
    const d0=Date.now();const r=await fetch('https://speed.cloudflare.com/__down?bytes=1000000&seed='+Math.random());await r.arrayBuffer();const ds=Math.max((Date.now()-d0)/1000,.1);
    const down=+(8/ds).toFixed(1);
    const payload='x'.repeat(180000);const u0=Date.now();await fetch('https://speed.cloudflare.com/__up',{method:'POST',body:payload});const us=Math.max((Date.now()-u0)/1000,.1);
    const up=+((payload.length*8/1e6)/us).toFixed(1);
    setResult({ping:Math.round(pingSamples.reduce((a,b)=>a+b,0)/pingSamples.length),download:down,upload:up});
  }catch(e){setResult(null);setError('Could not complete the network test. Check your connection and try again.')}finally{setTesting(false)}};
  const available=ispCoverage.filter(i=>i.states.includes(state));
  const score=(r:typeof result)=>!r?0:Math.max(0,Math.min(100,Math.round(100-r.ping*.55+Math.min(r.download,50)*.35+Math.min(r.upload,20)*.25)));
  const quality=!result?'Not tested':result.ping<45?'Tournament ready':result.ping<80?'Playable':'Risky for comp';
  return <Wrap title="CONNECTION CHECK" subtitle="Gaming-first network intelligence for Nigerian CODM players" onBack={onBack}>
    <View style={s.netHero}><Text style={s.eyebrow}>MATCH READINESS</Text><Text style={s.bigTitle}>Don't lose the gunfight before it starts.</Text><Text style={s.note}>A normal speed test tells you Mbps. Squad Hub focuses on what matters in a match: latency first, then stability and usable throughput.</Text>
      <View style={s.netGauge}><Text style={s.netGaugeValue}>{result?score(result):'--'}</Text><Text style={s.netGaugeLabel}>NETWORK SCORE</Text></View>
      <View style={s.metrics}><Metric value={result?result.ping+' ms':'--'} label="PING" accent/><Metric value={result?result.download+' Mbps':'--'} label="DOWNLOAD"/><Metric value={result?result.upload+' Mbps':'--'} label="UPLOAD"/><Metric value={quality} label="VERDICT"/></View>
      <ActionButton label={testing?'TESTING CONNECTION...':'RUN CONNECTION TEST'} onPress={run}/>{error?<Text style={s.netError}>{error}</Text>:null}</View>
    <SectionHeader title="ISP COVERAGE CHECKER"/>
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{gap:7,marginBottom:12}}>{nigeriaStates.map(x=><Pressable key={x} onPress={()=>setState(x)} style={[s.chip,state===x&&s.chipOn]}><Text style={[s.chipT,state===x&&s.chipTOn]}>{x}</Text></Pressable>)}</ScrollView>
    <Card>{available.map((i,idx)=><View key={i.name} style={[s.actionRow,idx<available.length-1&&s.border]}><View style={{flex:1}}><Text style={s.listTitle}>{i.name}</Text><Text style={s.muted}>{i.type} · {i.note}</Text></View><Pill text="REPORTED" tone="green"/></View>)}</Card>
    <SectionHeader title="BEST ISP FOR COMPETITIVE GAMING"/>
    <Card accent><Text style={s.cardTitle}>{available[0]?.name||'No data yet'} leads the starter dataset for {state}</Text><Text style={s.note}>This recommendation is intentionally simple at launch. As players submit tests, Squad Hub will rank ISPs by average ping, jitter/stability and successful match sessions per state.</Text><View style={s.statGrid}><MiniStat v="42 ms" l="AVG REPORTED PING"/><MiniStat v="87" l="GAMING SCORE"/><MiniStat v="24" l="USER TESTS"/></View></Card>
    <Text style={s.note}>Coverage shown here is a curated starter dataset, not a guarantee at street level. Nigerian network performance can change by neighborhood, congestion, device and time of day.</Text>
  </Wrap>
}
function PublicApi({onBack}:{onBack:()=>void}){return <Wrap title="PUBLIC API" subtitle="Approved public competitive data" onBack={onBack}><Card accent><Text style={s.eyebrow}>SQUAD HUB API v1</Text><Text style={s.bigTitle}>Build on the competitive record.</Text><Text style={s.note}>Public player, team, tournament, ranking and match data can power overlays, bots, stat sites and broadcasts. Contracts, private scouting notes and strategy data stay private.</Text></Card><SectionHeader title="EXAMPLE RESOURCES"/><Card><ActionRow title="GET /api/v1/rankings/mp" sub="Central MP rankings" status="PUBLIC"/><ActionRow title="GET /api/v1/players/{shid}" sub="Public Player Passport" status="PUBLIC"/><ActionRow title="GET /api/v1/tournaments" sub="Tournament discovery" status="PUBLIC"/><ActionRow title="GET /api/v1/matches/live" sub="Live official matches" status="PUBLIC"/></Card></Wrap>}

function MiniStat({v,l}:{v:string;l:string}){return <View style={s.miniStat}><Text style={s.miniV}>{v}</Text><Text style={s.miniL}>{l}</Text></View>}
function ToolTile({title,onPress}:{title:string;onPress?:()=>void}){return <Pressable onPress={onPress??(()=>Alert.alert(title,'This control is interactive in the prototype. Backend persistence for this specific tool is the next integration step.'))} style={s.tool}><View style={s.toolIcon}><Text style={s.toolIconT}>◆</Text></View><Text style={s.toolTitle}>{title}</Text><Text style={s.toolLink}>OPEN →</Text></Pressable>}
function ActionRow({title,sub,status}:{title:string;sub:string;status:string}){return <View style={s.actionRow}><View style={{flex:1}}><Text style={s.listTitle}>{title}</Text><Text style={s.muted}>{sub}</Text></View><Pill text={status} tone={status==='LIVE'||status==='ACTIVE'||status==='CONNECTED'||status==='APPROVED'||status==='VERIFIED'||status==='DONE'?'green':status==='URGENT'||status==='HIGH'?'red':'dark'}/></View>}

